(()=>{let index=0;const images=window.ZINE_IMAGES||[],photo=document.querySelector('.zine-photo'),counter=document.querySelector('.counter');const render=()=>{photo.src=images[index];counter.textContent=`${index+1} / ${images.length}`};document.querySelector('.prev')?.addEventListener('click',()=>{index=(index+images.length-1)%images.length;render()});document.querySelector('.next')?.addEventListener('click',()=>{index=(index+1)%images.length;render()});document.querySelector('.zine-language')?.addEventListener('click',e=>{e.currentTarget.textContent=e.currentTarget.textContent==='En'?'Ru':'En'});document.querySelector('.zine-burger')?.addEventListener('click',()=>location.href='index.html')})()
